// Package mathml converts TeX to MathML at build time with Temml
// (https://temml.org). Browsers render MathML natively, so pages with math
// load no JavaScript, only a small stylesheet and font from package bundled.
//
// The bundled script, like the stylesheets and fonts in package bundled, is
// generated by scripts/vendorjs from the version pinned in third_party/js;
// see third_party/README.md.
package mathml

import (
	_ "embed"
	"errors"
	"fmt"
	"strings"

	"github.com/MohamedElashri/nida/internal/jsengine"
	"github.com/MohamedElashri/nida/third_party/goja"
)

//go:embed files/temml.min.js.gz
var temmlSource []byte

var (
	pool  = jsengine.NewPool("Temml", temmlSource, "temml.renderToString")
	cache jsengine.Cache
)

// Error is TeX that Temml cannot parse.
type Error struct {
	TeX     string
	Display bool
	Message string
}

func (e *Error) Error() string {
	return fmt.Sprintf("math %s: %s", delimit(e.TeX, e.Display), e.Message)
}

// delimit writes TeX the way it appears in Markdown: $...$ inline and
// $$...$$ for display math.
func delimit(tex string, display bool) string {
	if display {
		return "$$" + tex + "$$"
	}
	return "$" + tex + "$"
}

// Render returns the TeX as a <math> element. Display math is a block
// element; inline math flows with the text.
func Render(tex string, display bool) (string, error) {
	key := "i" + tex
	if display {
		key = "d" + tex
	}
	if out, ok := cache.Get(key); ok {
		return out, nil
	}
	var out string
	err := pool.Run(func(vm *jsengine.VM) error {
		options := vm.NewObject()
		_ = options.Set("displayMode", display)
		_ = options.Set("throwOnError", true)
		result, err := vm.Entry(goja.Undefined(), vm.ToValue(tex), options)
		if err != nil {
			return err
		}
		out = result.String()
		return nil
	})
	if err != nil {
		return "", mathError(tex, display, err)
	}
	cache.Put(key, out)
	return out, nil
}

func mathError(tex string, display bool, err error) error {
	if errors.Is(err, jsengine.ErrTimeout) {
		return &Error{TeX: tex, Display: display, Message: "rendering " + err.Error()}
	}
	thrown := jsengine.Thrown(err)
	if thrown == nil {
		return err
	}
	msg := jsengine.String(thrown, "message")
	if jsengine.String(thrown, "name") != "ParseError" {
		// A bug inside Temml rather than a problem with the TeX.
		return fmt.Errorf("math %s: Temml failed: %s", delimit(tex, display), msg)
	}
	// Temml underlines the problem with combining low lines, which
	// terminals show poorly, and repeats the source after the position.
	msg = strings.ReplaceAll(msg, "\u0332", "")
	if i := strings.Index(msg, " at position "); i >= 0 {
		msg = msg[:i]
	}
	if i := strings.Index(msg, " at end of input"); i >= 0 {
		msg = msg[:i]
	}
	return &Error{TeX: tex, Display: display, Message: strings.TrimSpace(msg)}
}
